import json
from test import ANY, unittest, Mock, patch, mock_open
from taf.cloud.cbam.vnf.v4.vnf import VNF4

from taf.cloud.cbam.schemas.v4.vnf_instance import VnfInfo
from taf.cloud.cbam.schemas.v4.no_data import NoData
from taf.cloud.cbam.session import CbamResponse, CbamSession
from taf.cloud.cbam import exception
from taf.cloud.cbam.schemas.v4.vnf_lcm_op_occ import VnfLcmOpOcc


class TestVNF(unittest.TestCase):
    def setUp(self):
        self.m_client = Mock(spec=CbamSession)
        self.vnf = VNF4(self.m_client)

    def vnf_info_dict(self):
        return {'id': 'id', 'vnfdId': 'vnfdId', 'vnfProvider': 'vnfProvider',
                'vnfProductName': 'vnfProductName', 'vnfSoftwareVersion': 'vnfSoftwareVersion',
                'vnfdVersion': 'vnfdVersion', 'vnfPkgId': 'vnfPkgId',
                'instantiationState': 'instantiationState', '_links': '_links'}

    def vnf_info__list_of_dicts(self):
        return [{'id': 'id', 'vnfInstanceName': 'name', 'vnfdId': 'vnfdId', 'vnfProvider': 'vnfProvider',
                 'vnfProductName': 'vnfProductName', 'vnfSoftwareVersion': 'vnfSoftwareVersion',
                 'vnfdVersion': 'vnfdVersion', 'vnfPkgId': 'vnfPkgId',
                 'instantiationState': 'instantiationState', '_links': '_links'},
                {'id': 'id2', 'vnfInstanceName': 'name2', 'vnfdId': 'vnfdId2', 'vnfProvider': 'vnfProvider2',
                 'vnfProductName': 'vnfProductName2', 'vnfSoftwareVersion': 'vnfSoftwareVersion2',
                 'vnfdVersion': 'vnfdVersion2', 'vnfPkgId': 'vnfPkgId2',
                 'instantiationState': 'instantiationState2', '_links': '_links2'}]

    def test_createVnf_requestSend(self):
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=self.vnf_info_dict()), status_code=201))

        vnf_info = VnfInfo(vnfd_id=1, name='vnf', description='it is vnf')
        resp = self.vnf.create(vnf_info)

        expected_data = {'vnfInstanceDescription': 'it is vnf', 'vnfdId': 1, 'vnfInstanceName': 'vnf'}
        expected_url = 'vnflcm/v1/vnf_instances'
        actual_data = json.loads(self.m_client.send_request.call_args[1]['data'])
        actual_url = self.m_client.send_request.call_args[1]['endpoint']

        self.assertEqual(expected_url, actual_url)
        self.assertDictEqual(expected_data, actual_data)
        self.assertIsInstance(resp, VnfInfo)

    def test_queryOne_requestSendResponseReceived(self):
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=self.vnf_info_dict()), status_code=200))

        vnf_info = Mock()
        vnf_info.id = 2
        resp = self.vnf.query_one(vnf_info)

        self.m_client.send_request.assert_called_with(
            api_version='4.0',
            method='get', endpoint='vnflcm/v1/vnf_instances/2')

        self.assertIsInstance(resp, VnfInfo)

    def test_queryAllVNfs_requestSendResponseReceived(self):
        status_code = 200
        output = self.vnf_info__list_of_dicts()
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=output), status_code=status_code))

        resp = self.vnf.query_all_vnfs()
        self.m_client.send_request.assert_called_with(
            api_version='4.0',
            method='get', endpoint='vnflcm/v1/vnf_instances')
        for vnf_info in resp:
            self.assertIsInstance(vnf_info, VnfInfo)

    def test_givenValidVnfName_deleteVnf_shouldPass(self):
        self.m_client.send_request.side_effect = [
            CbamResponse(Mock(json=Mock(
                return_value=self.vnf_info__list_of_dicts()), status_code=200)),
            CbamResponse(Mock(json=Mock(return_value={}), status_code=204))
        ]
        vnf_info = Mock()
        vnf_info.name = 'name'
        self.vnf.delete_vnf(vnf_info)

    def test_givenInvalidVnfName_delete_shouldRaiseException(self):
        self.m_client.send_request = Mock(
            return_value=CbamResponse(
                Mock(json=Mock(return_value=self.vnf_info__list_of_dicts()),
                     status_code=200)))

        with self.assertRaises(exception.VnfNameNotFoundException):
            self.vnf.delete_vnf(Mock(name='other name'))


class TestVnfLifecycle(unittest.TestCase):
    def setUp(self):
        self.m_client = Mock(spec=CbamSession)
        self.vnf = VNF4(self.m_client)

        vnf = Mock()
        vnf.id = 'id'
        vnf.name = 'some name'

        self.vnf.query_all_vnfs = Mock(return_value=[vnf])

        self.input_data = {'some key': 'some value'}

    def test_givenValidArgs_instantiateVnf_callsPostWithCorrectParams(self):
        expected_endpoint = 'vnflcm/v1/vnf_instances/id/instantiate'
        json_content = None
        body_content = {'apiVersion': '4.0', 'key': 'value',
                        'vimConnectionInfo': [{'accessInfo': {'key': 'value'}}]}
        self.m_client.send_request.return_value = CbamResponse(
            Mock(json=Mock(return_value=json_content),
                 status_code=202))

        result = self.vnf.instantiate(name='some name',
                                      body_content=body_content,
                                      password='password')

        call_args = self.m_client.send_request.call_args[1]
        actual_data = json.loads(call_args['data'])

        self.assertIsInstance(result, NoData)
        self.assertDictEqual(body_content, actual_data)
        self.m_client.send_request.assert_called_with(
            method='post', endpoint=expected_endpoint,
            api_version='4.0',
            data=ANY)

    def test_givenAllParams_createInstatiateRequestBody_returnsCorrectBody(self):
        file_content = {'apiVersion': '4.0', 'key': 'value',
                        'vimConnectionInfo': [{'accessInfo': {'key': 'value'}}]}
        expected_body = {'key': 'value', 'flavourId': 'id',
                         'vimConnectionInfo': [{'accessInfo': {'key': 'value', 'password': 'password'}}]}

        output = self.vnf._create_instantiate_request_body(
            body=file_content, password='password', flavour_id='id')
        self.assertDictEqual(expected_body, json.loads(output))

    def test_givenValidArgs_modifyVnf_callsPatchWithCorrectParams(self):
        expected_endpoint = 'vnflcm/v1/vnf_instances/id'
        expected_data = json.dumps(self.input_data)
        self.m_client.send_request.return_value = CbamResponse(
            Mock(json=Mock(return_value={}),
                 status_code=202))

        result = self.vnf.modify(name='some name', parameters_to_change=expected_data)

        self.m_client.send_request.assert_called_with(
            api_version='4.0',
            method='patch', endpoint=expected_endpoint, data=expected_data)
        self.assertIsInstance(result, NoData)

    def test_givenName_terminateVnf_callsPostWithCorrectParams(self):
        expected_endpoint = 'vnflcm/v1/vnf_instances/id/terminate'
        expected_data = json.dumps({'terminationType': 'GRACEFUL'})
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value={}),
            status_code=202))

        result = self.vnf.terminate('some name')

        self.assertIsInstance(result, NoData)
        self.m_client.send_request.assert_called_with(method='post', api_version='4.0',
                                                      endpoint=expected_endpoint, data=expected_data)

    def test_givenAllParams_terminateVnf_callsPostWithCorrectParams(self):
        self.vnf.terminate('some name', termination_type='GRACEFUL',
                           termination_timeout=10)
        expected_endpoint = 'vnflcm/v1/vnf_instances/id/terminate'
        expected_data = json.dumps({'terminationType': 'GRACEFUL',
                                    'gracefulTerminationTimeout': 10})
        self.m_client.send_request.assert_called_with(
            api_version='4.0',
            method='post', endpoint=expected_endpoint, data=expected_data)

    def test_deleteVnf_whenResponseDoesntHaveJson_returnsNone(self):
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(side_effect=AttributeError), status_code=204))

        vnf = Mock()
        vnf.name = 'some name'
        response = self.vnf.delete_vnf(vnf)

        self.assertIsNone(response)

    @patch('taf.cloud.cbam.vnf.v4.vnf.open',
           mock_open(read_data='{"additionalParams": {"OptionalExtraParams": ""}}'))
    def _post_custom_operation_test(self, optional_parameter=None):
        output = None
        status_code = 202
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=output), status_code=status_code))

        if optional_parameter:
            response = self.vnf.post_custom_operation(
                VnfInfo(name='some name'), 'query', json.dumps(self.input_data))
            self.m_client.send_request.assert_called_once_with(
                api_version='4.0',
                method='post',
                endpoint='vnflcm/v1/vnf_instances/id/custom/query',
                data='{"additionalParams": {"OptionalExtraParams": ""}}')
        else:
            response = self.vnf.post_custom_operation(VnfInfo(name='some name'), 'query')
            self.m_client.send_request.assert_called_once_with(
                api_version='4.0',
                method='post',
                endpoint='vnflcm/v1/vnf_instances/id/custom/query')
        self.assertIsInstance(response, NoData)

    def test_postCustomOperation_passesWithRequiredParams(self):
        self._post_custom_operation_test()

    def test_postCustomOperation_passesWithAllParams(self):
        self._post_custom_operation_test(optional_parameter=True)

    def test_postCustomOperation_withAdditionalParamsAsDict_passes(self):
        output = None
        status_code = 202
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=output), status_code=status_code))

        response = self.vnf.post_custom_operation(
            VnfInfo(name='some name'), 'query', {'testParam': 'testParam'})
        self.m_client.send_request.assert_called_once_with(
            api_version='4.0',
            method='post',
            endpoint='vnflcm/v1/vnf_instances/id/custom/query',
            data='{"additionalParams": {"testParam": "testParam"}}')
        self.assertIsInstance(response, NoData)

    def test_getOperationExecutionInfo_passesWithProperParameters(self):
        expected_endpoint = 'vnflcm/v1/vnf_lcm_op_occs/12345'
        response_dict = {'id': 'arg1', 'operationState': 'arg2',
                         'stateEnteredTime': 'arg3', 'startTime': 'arg4',
                         'vnfInstanceId': 'arg5', 'grantId': 'arg6',
                         'operation': 'arg7', 'isCancelPending': 'arg',
                         'isAutomaticInvocation': 'arg8',
                         'operationParams': 'arg9',
                         '_links': {'self': {'href': 'arg10'}}}
        operation_id = VnfLcmOpOcc(operation_id='12345')
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=response_dict),
            status_code=200))

        result = self.vnf.get_operation_execution_info(operation_id)

        self.assertIsInstance(result, VnfLcmOpOcc)
        self.m_client.send_request.assert_called_with(method='get', api_version='4.0',
                                                      endpoint=expected_endpoint)

    def test_getAllOperationExecutionInfo_passesWithProperParameters(self):
        expected_endpoint = 'vnflcm/v1/vnf_lcm_op_occs'
        response_list = [{'id': 'arg1', 'operationState': 'arg2',
                          'stateEnteredTime': 'arg3', 'startTime': 'arg4',
                          'vnfInstanceId': 'arg5', 'grantId': 'arg6',
                          'operation': 'arg7', 'isCancelPending': 'arg',
                          'isAutomaticInvocation': 'arg8',
                          'operationParams': 'arg9',
                          '_links': {'self': {'href': 'arg10'}}}]
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=response_list),
            status_code=200))

        result = self.vnf.get_all_operation_execution_info(vnf_instance_name='some name', all_fields=True)

        self.assertIsInstance(result, list)
        self.m_client.send_request.assert_called_with(method='get', api_version='4.0',
                                                      endpoint=expected_endpoint,
                                                      params={'vnfInstanceId': 'id', 'all_fields': True})

    def test_getAllOperationExecutionInfo_passesWithDefaultParameters(self):
        expected_endpoint = 'vnflcm/v1/vnf_lcm_op_occs'
        response_list = [{'id': 'arg1', 'operationState': 'arg2',
                          'stateEnteredTime': 'arg3', 'startTime': 'arg4',
                          'vnfInstanceId': 'arg5', 'grantId': 'arg6',
                          'operation': 'arg7', 'isCancelPending': 'arg',
                          'isAutomaticInvocation': 'arg8',
                          'operationParams': 'arg9',
                          '_links': {'self': {'href': 'arg10'}}}]
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value=response_list),
            status_code=200))

        result = self.vnf.get_all_operation_execution_info(vnf_instance_name=None, all_fields=False)

        self.assertIsInstance(result, list)
        self.m_client.send_request.assert_called_with(method='get', api_version='4.0',
                                                      endpoint=expected_endpoint, params={})

    def test_givenValidArgs_upgradeVnf_callsPostWithCorrectParams(self):
        expected_endpoint = 'vnflcm/v1/vnf_instances/id/upgrade'
        expected_data = json.dumps({'vnfdId': 'new_package'})
        self.m_client.send_request.return_value = CbamResponse(Mock(
            json=Mock(return_value={'id': 'id',
                                    'vnfInstanceId': 'id',
                                    'operationType': 'type',
                                    'status': 'status',
                                    'startTime': 'startTime'}),
            status_code=202))

        result = self.vnf.upgrade(name='some name', vnfd_id='new_package')

        self.assertIsInstance(result, NoData)
        self.m_client.send_request.assert_called_with(
            api_version='4.0',
            method='post', endpoint=expected_endpoint, data=expected_data)
